<script setup lang="ts">
const api = useApi(); const route = useRoute(); const router = useRouter()
const form = reactive({ password: '', confirm: '' }); const error = ref(''); const loading = ref(false)
async function submit() { error.value = ''; if (form.password !== form.confirm) { error.value = 'Passwords do not match'; return }; loading.value = true; try { await api.request('/auth/reset', { method: 'POST', body: { token: route.query.token, password: form.password } }); router.push('/login') } catch (e: any) { error.value = e?.data?.message || 'Reset failed' } finally { loading.value = false } }
</script>
<template><section class="section-y"><div class="wrap max-w-md"><p class="label-mono text-signal-deep">Account recovery</p><h1 class="type-product-hero mt-2">Choose a new password.</h1><form class="mt-6 space-y-4" @submit.prevent="submit"><div><label class="field-label">New password</label><input v-model="form.password" type="password" minlength="8" required class="field"></div><div><label class="field-label">Confirm</label><input v-model="form.confirm" type="password" minlength="8" required class="field"></div><button class="btn btn-dark w-full" :disabled="loading">{{ loading ? 'Updating…' : 'Update password' }}</button><p v-if="error" class="text-[11px] text-signal-deep">{{ error }}</p></form></div></section></template>
